# As quatro aulas seguintes mantêm a mesma arquitetura, mas cada uma nasce de uma obra, uma situação,
# um léxico, cenas, escolhas e missões próprios.
def add_story(s):
    a,b=s['names']; V=s['vocab']; hot=[(x[0],x[1],x[2],x[4],x[5]) for x in V[:5]]
    gaps=[
      (s['gaps'][0][0],s['gaps'][0][1],s['gaps'][0][2],0,s['gaps'][0][3]),
      (s['gaps'][1][0],s['gaps'][1][1],s['gaps'][1][2],0,s['gaps'][1][3]),
      (s['gaps'][2][0],s['gaps'][2][1],s['gaps'][2][2],0,s['gaps'][2][3]),
      (s['gaps'][3][0],s['gaps'][3][1],s['gaps'][3][2],0,s['gaps'][3][3]),]
    traps=[(s['traps'][0][0],s['traps'][0][1],0,s['traps'][0][2]),(s['traps'][1][0],s['traps'][1][1],0,s['traps'][1][2])]
    R0=R(s['ids'][0],s['rule'][0],s['rule'][1],[s['rule'][2],s['rule'][3]],s['rule'][4],s['rule'][5],s['rule'][6],[s['rule'][7]])
    exps=[(x[0],x[1],'Expressão',x[2],x[3],x[4],x[5]) for x in s['exps']]
    exscene=[]
    for i,x in enumerate(s['exps']): exscene.append([a if i%2==0 else b,x[4],x[5]])
    exscene+=s['scene2extra']
    lab=s['lab']
    labd=dict(short=s['short'],title=s['labtitle'],say=s['labsay'],what=s['labwhat'],how=s['labhow'],pt=s['labpt'],ex=lab,pairs=s['pairs'],tip=s['labtip'],phrase=[hot[0][3],hot[0][4]],rounds=[(x[0],[x[0],x[4]],0,f'**{x[0]}** é a palavra da cena.') for x in lab])
    verbs=[dict(v=x[0],ic=x[1],pt=x[2],f=[['eu',x[3]],['ele/ela',x[4]]],ex=[x[5],x[6]],note=x[7]) for x in s['verbs']]
    mold=[(m[0],[('começo',[[m[1][0],m[1][1]]]),('fim',[[x,y] for x,y in m[2]])],'.') for m in s['molds']]
    quiz=[(q[0],q[1],[('🎯',q[2]),('🧩',q[3]),('🔎',q[4])],0,q[5],q[6]) for q in s['quiz']]
    E0=E(s['n'],s['title'],s['sub'],s['pattern'],s['why'],s['names'],s['ids'],s['rs'],s['obra'],hot,gaps,traps,R0,s['cover'],[(x[0],x[1],x[2],x[3]) for x in V],s['lines'],quiz,[[x[4],x[5]] for x in V[:4]],s['teaser'],exps,exscene,labd,('Verbos em ação',s['verbtip'],s['verbs']),mold,s['speak'],s['produce'],s['mission2'],scenes=s['scenes'],sc=s['rs'])
    EPS.append(E0)

