def compact(n,title,sub,pattern,why,names,ids,rs,obra,theme,vocab,lines,verbs,exps):
    """Autoria compacta: os elementos mecânicos derivam do léxico e das cenas exclusivos desta missão."""
    a,b=names
    hot=[(x[0],x[1],x[2],x[4],x[5]) for x in vocab[:5]]
    w=[x[1] for x in vocab]
    gaps=[(f"They had been ___ {theme['tail']}.",theme['pttail'],[w[0],'working','waiting'],0,'Had been + -ing mostra um processo em curso antes de outro marco passado.'),
          (f"By then, {a} had been ___ the evidence.",f'Até então, {a} vinha analisando as evidências.',[w[1],'ignored','to ignore'],0,f'Use {w[1]} em -ing depois de had been.'),
          (f"The detail had ___ the whole story.",'O detalhe tinha mudado toda a história.',['changed','changing','change'],0,'Depois de had, use o particípio.'),
          (f"We had been ___ the timeline.",'Nós vínhamos reconstruindo a linha do tempo.',['rebuilding','rebuilt','rebuild'],0,'Had been pede verbo em -ing.')]
    traps=[('Qual frase narra o processo antes do ponto passado?',[f'They had been {w[0]} {theme["tail"]}.',f'They have been {w[0]} {theme["tail"]}.',f'They had {w[0]}ing {theme["tail"]}.'],0,'A primeira coloca a atividade antes do marco passado.'),('Qual pergunta é bem formada?',[f'What had {a} been doing?',f'What {a} had been doing?',f'What had been {a} doing?'],0,'Had vem antes do sujeito; been vem antes do verbo em -ing.')]
    rule=R(ids[0],theme['head'],theme['rulesub'],[theme['say'],theme['ptsay']], [([['had been',2]],[[w[0],3],[theme['tail'],3]],f'had been {w[0]} {theme["tail"]}','processo antes de outro fato passado')], [('⏳','Processo',f'They had been {w[0]} {theme["tail"]}.',theme['ptsay']),('📍','Marco',theme['mark'],theme['ptmark']),('🎞️','Perspectiva',theme['perspective'],theme['ptperspective']),('🧭','Efeito',theme['effect'],theme['pteffect'])], [('sequência',1,'O processo vem antes do marco da narrativa.',theme['say']),('foco',2,'Escolha o tempo para destacar duração, não só resultado.',theme['effect'])],[theme['tip']])
    quiz=[('What had been happening?','O que vinha acontecendo?',theme['answer'],theme['wrong1'],theme['wrong2'],0,theme['whyq']),('What changed the interpretation?','O que mudou a interpretação?',theme['answer2'],theme['wrong3'],theme['wrong4'],2,theme['whyq2']),('What should they do next?','O que devem fazer depois?',theme['answer3'],theme['wrong5'],theme['wrong6'],4,theme['whyq3'])]
    L=[(w[0],vocab[0][3],vocab[0][2],theme['sound1'],w[0]+'s',vocab[0][3]),(w[1],vocab[1][3],vocab[1][2],theme['sound2'],w[1]+'ed',vocab[1][3]),(w[2],vocab[2][3],vocab[2][2],theme['sound3'],w[2]+'ing',vocab[2][3])]
    lab=dict(short='b2'+str(n)[-2:],title=f"Laboratório de som: {w[0]}, {w[1]} e {w[2]}",say='Ouça o ritmo de uma narrativa em reconstrução.',what=f'**{w[0]}**, **{w[1]}** e **{w[2]}** carregam as pistas da cena.',how='Repita as três palavras e depois a frase completa.',pt='Ligue had been ao verbo seguinte para preservar o ritmo.',ex=L,pairs=[(x[0],x[4],x[1]+' × '+x[5]) for x in L],tip='Primeiro diga o processo; depois diga o fato que o interrompeu.',phrase=[hot[0][3],hot[0][4]],rounds=[(x[0],[x[0],x[4]],0,f'**{x[0]}** é a palavra da cena.') for x in L])
    expdata=[(x[0],x[1],'Expressão',x[2],x[3],x[4],x[5]) for x in exps]
    exscene=[]
    for i,x in enumerate(exps): exscene.append([a if i%2==0 else b,x[4],x[5]])
    exscene += [[a,theme['sceneextra1'],theme['ptsceneextra1']],[b,theme['sceneextra2'],theme['ptsceneextra2']],[a,theme['sceneextra3'],theme['ptsceneextra3']],[b,theme['sceneextra4'],theme['ptsceneextra4']]]
    VB=[dict(v=x[0],ic=x[1],pt=x[2],f=[['eu',x[3]],['ele/ela',x[4]]],ex=[x[5],x[6]],note=x[7]) for x in verbs]
    molds=[('Linha do tempo',[('começo', [['They had been','eles vinham']]),('fim',[(f' {w[0]} {theme["tail"]}.',theme['ptsay']),(f' {w[1]} the evidence.',' analisando as evidências.'),(f' {w[2]} the details.',' registrando os detalhes.')])],'.'),('Pergunta',[('começo', [['What had been','o que vinha']]),('fim',[(f' happening before {theme["markshort"]}?',' acontecendo antes de '+theme['ptmarkshort']+'?'),(' changing the story?',' mudando a história?'),(' unclear to them?',' pouco claro para eles?')])],'.'),('Conclusão',[('começo', [['Once we','quando nós']]),('fim',[(' understand the sequence, we can decide.',' entendermos a sequência, poderemos decidir.'),(' compare the accounts, we can respond.',' compararmos os relatos, poderemos responder.'),(' name the gap, we can repair it.',' nomearmos a lacuna, poderemos repará-la.')])],'.')]
    prod=mission('🎬','Reconstrua a cena','Conte o processo e o fato que mudou a leitura.','Use had been + -ing, depois um marco passado e uma conclusão. ',f'They had been {w[0]} {theme["tail"]} when the new detail changed our view.', [('Usei had been?',r'\bhad been\b','They had been','Comece pelo processo.','Processo: ótimo.'),('Usei -ing?',r'\b'+w[0]+r'\b|\bworking\b|\bwaiting\b','had been '+w[0],'Use um verbo em -ing.','Forma: ótima.'),('Usei marco?',r'\bwhen\b|\bbefore\b|\bafter\b','when the detail changed','Inclua um marco passado.','Linha do tempo: ótima.')],['Você uniu duração, marco e interpretação.','Inclua processo, marco e conclusão.'])
    m2=mission('🧭','Mude o ponto de vista','Explique como uma nova perspectiva altera a decisão.','Use uma expressão da cena e uma consequência clara.',f'When we {exps[0][1]}, we can {theme["action"]}.', [('Usei expressão?',r'\b'+exps[0][1].replace(' ','\\s+')+r'\b','Use '+exps[0][1],'Inclua a expressão da cena.','Expressão: ótima.'),('Usei consequência?',r'\bcan\b|\bwill\b|\bshould\b','we can '+theme['action'],'Mostre a consequência.','Consequência: ótima.'),('Usei ação?',r'\b'+theme['action'].split()[0]+r'\b',theme['action'],'Nomeie a ação.','Ação: ótima.')],['Sua interpretação leva a uma ação concreta.','Diga qual perspectiva muda a decisão e o que fazer.'])
    E0=E(n,title,sub,pattern,why,names,ids,rs,obra,hot,gaps,traps,rule,(title+': uma missão narrativa B2',theme['say']),[(x[0],x[1],x[2],x[3]) for x in vocab],lines,[(q[0],q[1],[('🎯',q[2]),('🧩',q[3]),('🔎',q[4])],0,q[5],q[6]) for q in quiz],[[x[4],x[5]] for x in vocab[:4]],('Próxima missão',theme['teaser']),expdata,exscene,lab,('Verbos em ação','Quatro verbos para reconstruir, comparar e decidir.',verbs),molds,[[theme['say'],theme['ptsay']],[theme['effect'],theme['pteffect']]],prod,m2,scenes=theme['scenes'],sc=rs)
    EPS.append(E0)

compact(83003,'Stories That Refuse One Timeline','comparar relatos e alternar passado simples, contínuo e perfeito','tempos narrativos · foco, sequência e ponto de vista','Você vai alternar tempos verbais para mostrar o que aconteceu, o que estava ocorrendo e o que já tinha mudado.',('Iris','Gabriel'),['polly','tommy'],'library',work('Beloved','romance de Toni Morrison',1987,'Beloved trata a memória como algo que retorna, interrompe e exige várias camadas de tempo. A aula não resume a obra: usa sua estrutura de memória para praticar como uma narrativa muda quando o passado invade o presente.',['The story had been shifting before anyone named the loss.','A história vinha mudando antes que alguém nomeasse a perda.'],'library','📚'),
 {'head':'Mais de uma camada de tempo','rulesub':'Escolha o tempo pelo foco da cena, não pela tradução palavra a palavra.','say':'The story had been shifting before anyone named the loss.','ptsay':'A história vinha mudando antes que alguém nomeasse a perda.','tail':'the account','pttail':'Eles vinham reorganizando o relato.','mark':'A witness finally spoke.','ptmark':'Uma testemunha finalmente falou.','markshort':'the witness spoke','ptmarkshort':'a testemunha falar','perspective':'Each voice changed the timeline.','ptperspective':'Cada voz mudou a linha do tempo.','effect':'We could not treat one version as complete.','pteffect':'Não podíamos tratar uma versão como completa.','tip':'Mude de tempo quando muda o foco: evento, processo ou anterioridade.','answer':'The account had been shifting.','wrong1':'The account will shift.','wrong2':'The account is simple.','whyq':'A fala destaca um processo anterior ao depoimento.','answer2':'A witness finally spoke.','wrong3':'The library closed.','wrong4':'They forgot the story.','whyq2':'O novo depoimento altera a leitura da sequência.','answer3':'Compare the versions.','wrong5':'Choose the fastest version.','wrong6':'Ignore the gap.','whyq3':'A tarefa é comparar perspectivas.','sound1':'o som final é curto','sound2':'o acento cai na primeira sílaba','sound3':'o ing mantém a ação aberta','scenes':['library','hall','street','cafe2','park','office'],'action':'compare the versions','sceneextra1':'That detail changes how I read the first scene.','ptsceneextra1':'Esse detalhe muda como leio a primeira cena.','sceneextra2':'Exactly; the timeline is not a single straight line.','ptsceneextra2':'Exatamente; a linha do tempo não é uma linha reta única.','sceneextra3':'Let’s mark what each witness knew at the time.','ptsceneextra3':'Vamos marcar o que cada testemunha sabia naquele momento.','sceneextra4':'Then our summary can show uncertainty honestly.','ptsceneextra4':'Então nosso resumo pode mostrar a incerteza com honestidade.','teaser':'Uma voz presente pode transformar uma cena passada.'},
 [('🧵','shifting','mudando','SHÍF-ting','The account had been shifting all night.','O relato vinha mudando a noite toda.'),('🗣️','witness','testemunha','UÍT-ness','A witness changed the sequence.','Uma testemunha mudou a sequência.'),('📍','sequence','sequência','SÍ-kwens','We need the sequence of events.','Precisamos da sequência dos eventos.'),('🧠','memory','memória','MÉ-mo-ri','Memory can alter a story.','A memória pode alterar uma história.'),('🔍','contradiction','contradição','kon-tra-DÍK-shon','The contradiction mattered.','A contradição importava.'),('🪞','perspective','perspectiva','per-SPÉK-tiv','Her perspective was different.','A perspectiva dela era diferente.')],
 [['Iris','The first account sounded certain.','O primeiro relato parecia certo.'],['Gabriel','Until the witness described a different sequence.','Até que a testemunha descreveu uma sequência diferente.'],['Iris','Had the story been shifting before that?','A história vinha mudando antes disso?'],['Gabriel','Yes. People had been avoiding one contradiction.','Sim. As pessoas vinham evitando uma contradição.'],['Iris','So the memory is not just background.','Então a memória não é apenas pano de fundo.'],['Gabriel','No. It changes what each person could know.','Não. Ela muda o que cada pessoa podia saber.'],['Iris','Let’s separate the event from each perspective.','Vamos separar o evento de cada perspectiva.'],['Gabriel','That is the only fair way to summarize it.','Esse é o único modo justo de resumi-lo.']],
 [('trace','🧵','rastrear','I trace','she traces','We traced the sequence carefully.','Rastreamos a sequência com cuidado.','trace + objeto'),('contradict','⚡','contradizer','I contradict','she contradicts','The details contradicted each other.','Os detalhes se contradiziam.','contradict + objeto'),('recount','🗣️','relatar','I recount','she recounts','She recounted the evening slowly.','Ela relatou a noite lentamente.','recount + evento'),('distinguish','🔎','distinguir','I distinguish','she distinguishes','We distinguished memory from fact.','Distinguimos memória de fato.','distinguish A from B')],
 [('🧩','fill in the gaps','preencher as lacunas','Use ao reconstruir uma sequência incompleta.','We need to **fill in the gaps** first.','Precisamos preencher as lacunas primeiro.'),('🔄','see it differently','ver de outro modo','Use quando outra perspectiva muda a leitura.','After her account, I **see it differently**.','Depois do relato dela, vejo de outro modo.'),('🗺️','put events in order','colocar eventos em ordem','Use para montar uma linha do tempo.','Let’s **put the events in order**.','Vamos colocar os eventos em ordem.'),('🧷','leave out','deixar de fora','Use para notar uma omissão relevante.','He **left out** one important detail.','Ele deixou de fora um detalhe importante.')])

compact(7083003,'Whose Version of the Evening?','testar a confiabilidade de relatos concorrentes','tempos narrativos · evidência, versão e inferência','Você vai comparar relatos contraditórios sem fingir certeza onde há lacuna.',('Sofia','Miles'),['polly','tom'],'street',work('Rashomon','filme de Akira Kurosawa',1950,'Rashomon apresenta um mesmo acontecimento por relatos incompatíveis. Em vez de procurar uma “fala certa” imediata, a aula ensina a separar observação, inferência e versão.',['They had been protecting their own versions of the evening.','Eles vinham protegendo suas próprias versões da noite.'],'street','🌧️'),
 {'head':'Relato não é fato bruto','rulesub':'Marque o que aconteceu, o que alguém dizia e o que você infere.','say':'They had been protecting their own versions of the evening.','ptsay':'Eles vinham protegendo suas próprias versões da noite.','tail':'their versions of the evening','pttail':'Eles vinham protegendo suas versões da noite.','mark':'The final account introduced a new detail.','ptmark':'O relato final introduziu um novo detalhe.','markshort':'the final account arrived','ptmarkshort':'o relato final chegar','perspective':'Every narrator framed the same event differently.','ptperspective':'Cada narrador enquadrou o mesmo evento de modo diferente.','effect':'We needed evidence before drawing a conclusion.','pteffect':'Precisávamos de evidência antes de concluir.','tip':'Use past perfect continuous para o processo; use linguagem cautelosa para a inferência.','answer':'They had been protecting their versions.','wrong1':'They were all agreeing.','wrong2':'They will protect a version.','whyq':'A frase mostra uma postura em andamento antes do relato final.','answer2':'A new detail in the final account.','wrong3':'The rain stopped.','wrong4':'The street was empty.','whyq2':'É o detalhe novo que muda a inferência.','answer3':'Separate evidence from interpretation.','wrong5':'Choose the loudest voice.','wrong6':'Delete the conflicting account.','whyq3':'A prática responsável separa evidência e interpretação.','sound1':'o ar sai no início','sound2':'o som termina em z','sound3':'o r é breve','scenes':['street','hall','office','cafe2','library','park'],'action':'separate evidence from interpretation','sceneextra1':'Let’s not treat confidence as proof.','ptsceneextra1':'Não vamos tratar confiança como prova.','sceneextra2':'Agreed; we need to compare what each person saw.','ptsceneextra2':'Concordo; precisamos comparar o que cada pessoa viu.','sceneextra3':'One detail may be missing, not false.','ptsceneextra3':'Um detalhe pode estar ausente, não ser falso.','sceneextra4':'That distinction keeps our conclusion fair.','ptsceneextra4':'Essa distinção mantém nossa conclusão justa.','teaser':'Uma voz no presente pode tornar uma lembrança mais viva.'},
 [('🛡️','protecting','protegendo','pro-TÉK-ting','They had been protecting their version.','Eles vinham protegendo sua versão.'),('🧾','testimony','depoimento','TÉS-ti-mo-ni','Her testimony changed the case.','O depoimento dela mudou o caso.'),('🔎','evidence','evidência','É-vi-dens','We need evidence, not confidence.','Precisamos de evidência, não de confiança.'),('⚖️','reliable','confiável','ri-LÁI-a-bol','Is this account reliable?','Esse relato é confiável?'),('🌧️','shelter','abrigo','SHÉL-ter','They waited under the shelter.','Eles esperaram sob o abrigo.'),('🧠','inference','inferência','ÍN-fe-rens','That is an inference, not a fact.','Isso é uma inferência, não um fato.')],
 [['Sofia','The three accounts cannot all be exact.','Os três relatos não podem ser todos exatos.'],['Miles','No, but each may preserve a different piece.','Não, mas cada um pode preservar uma peça diferente.'],['Sofia','They had been protecting their own versions.','Eles vinham protegendo suas próprias versões.'],['Miles','That does not mean every detail is invented.','Isso não significa que cada detalhe seja inventado.'],['Sofia','What evidence do we have apart from testimony?','Que evidência temos além de depoimento?'],['Miles','The shelter camera shows who arrived first.','A câmera do abrigo mostra quem chegou primeiro.'],['Sofia','Then we can test the timeline without accusing anyone.','Então podemos testar a linha do tempo sem acusar ninguém.'],['Miles','Exactly. Certainty is not the same as reliability.','Exatamente. Certeza não é o mesmo que confiabilidade.']],
 [('observe','👁️','observar','I observe','she observes','We observed the arrival times.','Observamos os horários de chegada.','observe + objeto'),('infer','🧠','inferir','I infer','she infers','We cannot infer intent from tone alone.','Não podemos inferir intenção só pelo tom.','infer from'),('verify','✅','verificar','I verify','she verifies','The camera verified the order.','A câmera verificou a ordem.','verify + objeto'),('withhold','🤫','reter','I withhold','she withholds','He withheld one detail.','Ele reteve um detalhe.','withhold + objeto')],
 [('🧊','hold back','reter / não revelar','Use para notar que alguém não contou tudo.','He may have **held back** a detail.','Ele pode ter retido um detalhe.'),('⚖️','weigh the evidence','pesar as evidências','Use antes de decidir entre versões.','We should **weigh the evidence**.','Devemos pesar as evidências.'),('🔎','read into','interpretar demais','Use para frear inferências excessivas.','Don’t **read too much into** one pause.','Não interprete demais uma pausa.'),('🧭','keep an open mind','manter a mente aberta','Use ao adiar uma conclusão.','Let’s **keep an open mind** for now.','Vamos manter a mente aberta por enquanto.')])

compact(83005,'A Present Tense Camera','usar o presente narrativo para aproximar uma cena do ouvinte','presente narrativo · imediatismo, foco e mudança de cena','Você vai narrar uma sequência passada no presente para criar proximidade sem perder a linha do tempo.',('Ava','Leo'),['polly','tommy'],'street',work('Mrs Dalloway','romance de Virginia Woolf',1925,'Mrs Dalloway acompanha um dia por movimentos de atenção, memória e cidade. A aula usa o presente narrativo como uma câmera: ele aproxima o leitor de uma ação, enquanto marcadores claros preservam o tempo da história.',['She steps outside, and the whole street changes.','Ela sai, e a rua inteira muda.'],'street','🌿'),
 {'head':'A câmera entra na cena','rulesub':'O presente narrativo aproxima uma ação; os marcadores mantêm o tempo legível.','say':'She steps outside, and the whole street changes.','ptsay':'Ela sai, e a rua inteira muda.','tail':'through the crowded street','pttail':'Eles vinham atravessando a rua cheia.','mark':'Earlier that morning, she had missed the bus.','ptmark':'Mais cedo naquela manhã, ela tinha perdido o ônibus.','markshort':'she misses the bus','ptmarkshort':'ela perder o ônibus','perspective':'The present makes the reader stand beside her.','ptperspective':'O presente faz o leitor ficar ao lado dela.','effect':'We can feel the decision as it happens.','pteffect':'Podemos sentir a decisão enquanto ela acontece.','tip':'Use o presente na cena viva; use marcadores para voltar e avançar no tempo.','answer':'She steps outside.','wrong1':'She will step outside.','wrong2':'She had stepping outside.','whyq':'O presente narrativo descreve a ação como se ocorresse agora.','answer2':'She had missed the bus earlier.','wrong3':'She misses every bus.','wrong4':'She will miss the bus.','whyq2':'Earlier that morning marca anterioridade real dentro da narração.','answer3':'Anchor the shift with a time marker.','wrong5':'Remove every time marker.','wrong6':'Use only one tense forever.','whyq3':'Marcadores evitam confusão quando a narrativa se move.','sound1':'o passo final é curto','sound2':'a vogal central é reduzida','sound3':'o r conecta à palavra seguinte','scenes':['street','park','cafe2','hall','home1','office'],'action':'anchor the shift with a time marker','sceneextra1':'The present tense puts us beside her.','ptsceneextra1':'O presente nos coloca ao lado dela.','sceneextra2':'And the earlier marker keeps the sequence clear.','ptsceneextra2':'E o marcador anterior mantém a sequência clara.','sceneextra3':'Now the memory can enter without confusing us.','ptsceneextra3':'Agora a memória pode entrar sem nos confundir.','sceneextra4':'That is a deliberate camera move, not an error.','ptsceneextra4':'Esse é um movimento deliberado de câmera, não um erro.','teaser':'Na próxima aula, uma escolha pequena abre uma nova possibilidade.'},
 [('🚪','steps outside','sai','stéps aut-SÁID','She steps outside without a coat.','Ela sai sem casaco.'),('🚦','notices','percebe','NÔU-ti-siz','He notices the light change.','Ele percebe a luz mudar.'),('🧭','turns','vira','târns','She turns toward the park.','Ela vira em direção ao parque.'),('🗣️','interrupts','interrompe','in-te-RÂPTS','A voice interrupts her thought.','Uma voz interrompe o pensamento dela.'),('🪟','glances','olha rapidamente','GLÉN-siz','He glances at the window.','Ele olha rapidamente para a janela.'),('🕰️','meanwhile','enquanto isso','MÍN-uáil','Meanwhile, the bus leaves.','Enquanto isso, o ônibus sai.')],
 [['Ava','She steps outside, and the noise hits her at once.','Ela sai, e o barulho a atinge de uma vez.'],['Leo','You are telling it as if it is happening now.','Você está contando como se estivesse acontecendo agora.'],['Ava','That is the point: the present brings us closer.','Esse é o ponto: o presente nos aproxima.'],['Leo','But when did she miss the bus?','Mas quando ela perdeu o ônibus?'],['Ava','Earlier that morning, she had missed it.','Mais cedo naquela manhã, ela o tinha perdido.'],['Leo','So the marker handles the jump back.','Então o marcador cuida do salto para trás.'],['Ava','Exactly. Then she turns toward the park.','Exatamente. Então ela vira em direção ao parque.'],['Leo','Now I can see the scene instead of just receiving a summary.','Agora consigo ver a cena, em vez de só receber um resumo.']],
 [('frame','🖼️','enquadrar','I frame','she frames','The narrator frames one small gesture.','O narrador enquadra um gesto pequeno.','frame + objeto'),('shift','🔄','mudar','I shift','she shifts','The scene shifts to the street.','A cena muda para a rua.','shift to'),('glance','👀','olhar rapidamente','I glance','she glances','She glances at the clock.','Ela olha rapidamente para o relógio.','glance at'),('anchor','⚓','ancorar','I anchor','she anchors','The phrase anchors the timeline.','A frase ancora a linha do tempo.','anchor + objeto')],
 [('🎥','zoom in on','aproximar o foco de','Use para focar em um detalhe da cena.','The narration **zooms in on** her hand.','A narração aproxima o foco da mão dela.'),('⏪','flash back to','voltar a','Use para sinalizar retorno ao passado.','The chapter **flashes back to** the morning.','O capítulo volta à manhã.'),('📍','in the moment','no momento','Use para descrever imersão na cena.','We stay **in the moment** with her.','Ficamos no momento com ela.'),('🧵','carry on','seguir','Use para retomar a ação principal.','Then the story **carries on** outside.','Então a história segue do lado de fora.')])
